// VULNERABLE - token concatenated into SQL; every response looks identical to the user...
const sql = "SELECT id FROM sessions WHERE token = '" + token + "'";
db.prepare(sql).get(); // ...but a CASE WHEN branch makes the DB slow ONLY when a condition holds
res.send('processing'); // real engines: ... THEN pg_sleep(3) - the wait leaks the answer

secureCode.code:
// SECURE - bind the token; input never becomes SQL, so no branch can be steered
db.prepare('SELECT id FROM sessions WHERE token = ?').get(token);
res.send('processing');
// You cannot patch a timing side channel by hiding output - the answer leaks through the clock.
// Keep input OUT of the SQL (bind), and apply least privilege so a session check cannot read staff.
